    }
    internal static int HtGolden(byte[] pdf, System.Text.StringBuilder t, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pg, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout, emon.Port.Cells ord, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells gp, emon.Port.Cells mst, emon.Port.Cells sf, emon.Port.Cells sc, emon.Port.Cells hc, emon.Port.Cells ws, emon.Port.Cells tmp2, emon.Port.Cells pr, emon.Port.Cells ptxt) {
        // PDF -> content -> headings -> paragraphs and sections -> Model -> pretty JSON; answer 0 when every step
        // answered 0, else a code naming the step (1 open, 2 content, 3 the Model's check). The JSON is `t`.
        emon.Port.CellsDrop(gl, 0);
        emon.Port.CellsDrop(et, 0);
        emon.Port.CellsDrop(mk, 0);
        emon.Port.CellsDrop(fnt, 0);
        emon.Port.CellsDrop(wd, 0);
        emon.Port.CellsDrop(ln, 0);
        emon.Port.Src src = emon.Port.SrcOfBlob(pdf);
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells gx = emon.Port.NewCells();
        int o = Pdfdoc.PdOpen(src, ar, dc, a, b, st);
        if (o != 0) {
            return 1;
        }
        if (Pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx) != 0) {
            return 2;
        }
        Heading.HdAnalyze(wd, ln, et, gl, sf, sc, hc, ws, tmp2, pr, ptxt);
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Para.PaPages(pg, pages);
        int np = emon.Port.CellsLen(pages) / 16;
        HtPa(wd, ln, et, np, pages, layout, nodes, attrs, regions, text, ord, raw, tmp, fr, gp, hc);
        if (Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, mst) != 0) {
            return 3;
        }
        Json.JsEmit(t, 1, nodes, attrs, regions, text, pages, ledger, layout, emon.Port.NewCells(), emon.Port.NewCells());
        return 0;
    }
